from checks import available
def reserve(stock, requests):
    request_dict = {}
    for sku, quantity in requests:
        if quantity <= 0:
            raise ValueError('nonpositive quantity')
        if sku not in request_dict:
            request_dict[sku] = quantity
        else:
            request_dict[sku] += quantity

    for sku, quantity in request_dict.items():
        if not available(stock, sku, quantity): raise ValueError('unavailable')
        stock[sku] -= quantity
    return stock

